from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class CablinkParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if int(self.mo_num) <= self.enb_ent_config['radios_count']:
            self.set_cablink_for_radio(execution_config)
        else:
            self.set_cablink_for_bbmod(execution_config)

    def set_cablink_for_radio(self, execution_config):
        radio_ent = self.enb_ent_config['radios'][self.mo_num]
        enb_id = self.enb_ent_config['id']

        self.set_radioProtocolType(radio_ent, execution_config)
        self.set_firstEndpointDN(radio_ent, execution_config)
        self.set_parameter('firstEndpointLabel', "OPT")

        if radio_ent.get('rmod'):
            self.drop_parameter('firstEndpointPortId')
            self.drop_parameter('linkModeConfiguration')
            self.drop_parameter('linkModeDC')
            self.drop_parameter('linkModeData')
            self.drop_parameter('linkModeSynchronization')
        else:
            self.set_parameter('firstEndpointPortId', radio_ent.get('port'))
            self.set_parameter('linkModeConfiguration', "false")
            self.set_parameter('linkModeDC', "false")
            self.set_parameter('linkModeData', "false")
            self.set_parameter('linkModeSynchronization', "false")

        self.set_linkSpeed(radio_ent)
        self.set_secondEndpointLabel(radio_ent)
        self.set_secondEndpointPortId(radio_ent)
        self.set_parameter('secondEndpointDN', f"MRBTS-{enb_id}/EQM-1/APEQM-1/RMOD-{self.mo_num}")
        self.set_iqCompression(radio_ent, execution_config)

    def set_cablink_for_bbmod(self, execution_config):
        bbmod_index = str(int(self.mo_num) - self.enb_ent_config['radios_count'])
        bbmod_ent = self.enb_ent_config['bbmods'][bbmod_index]
        enb_id = self.enb_ent_config['id']

        if execution_config['is_fsm4']:
            self.set_parameter('firstEndpointDN', f"MRBTS-{enb_id}/EQM-1/APEQM-1/CABINET-1/SMOD-{bbmod_ent.get('smod', '')}")
            self.set_parameter('firstEndpointLabel', "BACKPLANE")
            self.set_parameter('firstEndpointPortId', bbmod_ent.get('port'))
            self.set_parameter('linkModeConfiguration', "false")
            self.set_parameter('linkModeDC', "false")
            self.set_parameter('linkModeData', "false")
            self.set_parameter('linkModeSynchronization', "false")
            self.set_parameter('secondEndpointDN', f"MRBTS-{enb_id}/EQM-1/APEQM-1/CABINET-1/BBMOD-{bbmod_index}")
            self.set_parameter('secondEndpointLabel', "QSFP")

        else:
            self.set_parameter('firstEndpointDN', f"MRBTS-{enb_id}/EQM-1/APEQM-1/CABINET-1/SMOD-1")
            self.set_parameter('firstEndpointPortId', bbmod_ent.get('port'))
            self.set_parameter('linkModeConfiguration', "false")
            self.set_parameter('linkModeDC', "false")
            self.set_parameter('linkModeData', "false")
            self.set_parameter('linkModeSynchronization', "false")
            self.set_parameter('secondEndpointDN', f"MRBTS-{enb_id}/EQM-1/APEQM-1/CABINET-1/BBMOD-{bbmod_index}")
            label = bbmod_ent.get('label')
            if not label:
                label = 'QSFP'
                self.set_parameter('secondEndpointLabel', label)
            self.set_parameter('firstEndpointLabel', label)

    def set_radioProtocolType(self, radio_ent, execution_config):
        if radio_ent.get('protocol_type'):
            if execution_config['release'] >= 21:
                self.set_parameter('radioProtocolType', radio_ent.get('protocol_type'))

    def set_firstEndpointDN(self, radio_ent, execution_config):
        enb_id = self.enb_ent_config['id']
        if radio_ent.get('smod'):
            firstEndpointDN = f"MRBTS-{enb_id}/EQM-1/APEQM-1/CABINET-1/SMOD-{radio_ent['smod']}"
        elif radio_ent.get('rmod'):
            firstEndpointDN = f"MRBTS-{enb_id}/EQM-1/APEQM-1/RMOD-{radio_ent['rmod']}"
        elif execution_config['is_fsm4'] or radio_ent.get('bbmod'):
            firstEndpointDN = f"MRBTS-{enb_id}/EQM-1/APEQM-1/CABINET-1/BBMOD-{radio_ent.get('bbmod', '1')}"
        else:
            firstEndpointDN = f"MRBTS-{enb_id}/EQM-1/APEQM-1/CABINET-1/SMOD-1"

        self.set_parameter('firstEndpointDN', firstEndpointDN)

    def set_linkSpeed(self, radio_ent):
        if radio_ent.get('link_speed'):
            if radio_ent.get('link_speed') == '6Gbps':
                self.set_parameter('linkSpeed', 'Obsai6Gbps')
            elif radio_ent.get('link_speed') == '3Gbps':
                self.set_parameter('linkSpeed', 'Obsai3Gbps')
            else:
                self.set_parameter('linkSpeed', radio_ent.get('link_speed'))
        else:
            self.drop_parameter('linkSpeed')

    def set_secondEndpointLabel(self, radio_ent):
        if radio_ent.get('smod'):
            self.set_parameter('secondEndpointLabel', 'SFP')
        else:
            self.set_parameter('secondEndpointLabel', 'OPT')

    def set_secondEndpointPortId(self, radio_ent):
        if radio_ent.get('second_endpoint_port_id'):
            self.set_parameter('secondEndpointPortId', radio_ent['second_endpoint_port_id'])
        elif radio_ent.get('smod'):
            self.set_parameter('secondEndpointPortId', 1)
        else:
            self.drop_parameter('secondEndpointPortId')

    def set_iqCompression(self, radio_ent, execution_config):
        if radio_ent.get('iq_compression'):
            iq_compression = radio_ent['iq_compression']
            if execution_config['release'] >= 25.32508:
                if iq_compression == "eCPRI IQ9_E7":
                    iq_compression = "eCPRI IQ9"
            self.set_parameter('iqCompression', iq_compression)
        else:
            self.drop_parameter('iqCompression')
